def payments_from_instalments(apps, schema_editor):
    """पहिले किस्तामै राखिएको असुली → रसिदअनुसार भुक्तानी रेकर्ड."""
    I = apps.get_model("projects", "RevenueInstalment")
    Pay = apps.get_model("projects", "RevenuePayment")
    for i in I.objects.filter(paid_amount__gt=0):
        no = i.receipt_no or f"पुरानो-{i.id}"
        while Pay.objects.filter(receipt_no=no).exists():
            no += "-१"
        Pay.objects.create(instalment=i, date=i.paid_on or i.due_date, amount=i.paid_amount, receipt_no=no)


